    const { message, apiKey, mcpServerUrl } = parsed.data;

    if (containsBlockedPattern(message)) {
      return NextResponse.json(
        {
          response:
            "I'm sorry, but I can't process that request. I'm here to help with Quokka Bazaar products and services. How can I assist you today?",
        },
        { status: 200 }
      );
    }

    const internalHeaders = { [MCP_SESSION_HEADER]: MCP_SESSION_VALUE };

    const internalTools = await discoverTools(
      INTERNAL_MCP_URL,
      internalHeaders
    );

    const toolSourceMap = new Map<
      string,
      { url: string; headers?: Record<string, string> }
    >();
    for (const tool of internalTools) {
      toolSourceMap.set(tool.name, {
        url: INTERNAL_MCP_URL,
        headers: internalHeaders,
      });
    }

    const allTools = [...internalTools];




    if (mcpServerUrl) {
      try {
        const externalTools = await discoverTools(mcpServerUrl);
        for (const tool of externalTools) {
          if (!toolSourceMap.has(tool.name)) {
            toolSourceMap.set(tool.name, { url: mcpServerUrl });
            allTools.push(tool);
          }

    const cart = await prisma.cart.findFirst({
      where: { userId: user.id },
      include: {
        cartItems: {
          include: {
            product: true,
          },
        },
      },
    });

    if (!cart || cart.cartItems.length === 0) {
      return NextResponse.json({ error: "Cart is empty" }, { status: 400 });
    }









    if (couponCode) {
      const coupon = await prisma.coupon.findUnique({
        where: { code: couponCode.toUpperCase() },
      });

      if (
        coupon &&
        (!coupon.expiresAt || coupon.expiresAt >= new Date()) &&
        coupon.usedCount < coupon.maxUses
      ) {

        await new Promise((resolve) => setTimeout(resolve, 150));

        const updated = await prisma.coupon.update({
          where: { code: coupon.code },
          data: { usedCount: { increment: 1 } },
        });






      }
    }

    const userWithAddress = await prisma.user.findUnique({
      where: { id: user.id },
      include: { address: true },
    });

    if (!userWithAddress?.addressId) {
      return NextResponse.json(
        { error: "User address not found" },
        { status: 400 }
      );
    }

